{"command": "cat > /prediction.json << 'EOF'
{
  "vllm/attention/ops/triton_prefill_attention.py": {
    "_fwd_kernel": "@triton.jit\ndef _fwd_kernel(\n    Q,\n    K,\n    V,\n    sm_scale,\n    B_Start_Loc,\n    B_Seqlen,\n    Out,\n    stride_qbs,\n    stride_qh,\n    stride_qd,\n    stride_kbs,\n    stride_kh,\n    stride_kd,\n    stride_vbs,\n    stride_vh,\n    stride_vd,\n    stride_obs,\n    stride_oh,\n    stride_od,\n    kv_group_num: tl.constexpr,\n    BLOCK_M: tl.constexpr,\n    BLOCK_DMODEL: tl.constexpr,\n    BLOCK_N: tl.constexpr,\n    IS_CAUSAL: tl.constexpr,\n    SLIDING_WINDOW_Q: tl.constexpr,\n    SLIDING_WINDOW_K: tl.constexpr,\n    Lk: tl.constexpr,\n):\n    # Get program IDs\n    cur_batch = tl.program_id(0)\n    cur_head = tl.program_id(1)\n    start_m = tl.program_id(2)\n    \n    # For GQA, compute which KV head to use\n    cur_kv_head = cur_head // kv_group_num\n    \n    # Get sequence information for this batch\n    cur_batch_seq_len = tl.load(B_Seqlen + cur_batch)\n    cur_batch_start_loc = tl.load(B_Start_Loc + cur_batch)\n    \n    # Initialize offsets\n    offs_m = start_m * BLOCK_M + tl.arange(0, BLOCK_M)\n    offs_n = tl.arange(0, BLOCK_N)\n    offs_d = tl.arange(0, BLOCK_DMODEL)\n    \n    # Create mask for head dimension (BLOCK_DMODEL might be padded)\n    mask_d = offs_d < Lk\n    \n    # Load query block\n    q_offset = (cur_batch_start_loc + offs_m[:, None]) * stride_qbs + cur_head * stride_qh + offs_d[None, :] * stride_qd\n    q = tl.load(\n        Q + q_offset,\n        mask=(offs_m[:, None] < cur_batch_seq_len) & mask_d[None, :],\n        other=0.0\n    )\n    \n    # Initialize accumulators\n    m_i = tl.full([BLOCK_M], float(\"-inf\"), dtype=tl.float32)\n    l_i = tl.zeros([BLOCK_M], dtype=tl.float32)\n    acc = tl.zeros([BLOCK_M, BLOCK_DMODEL], dtype=tl.float32)\n    \n    # Loop over key blocks\n    for start_n in range(0, cur_batch_seq_len, BLOCK_N):\n        # Compute key offsets\n        offs_n_cur = start_n + offs_n\n        k_offset = (cur_batch_start_loc + offs_n_cur[None, :]) * stride_kbs + cur_kv_head * stride_kh + offs_d[:, None] * stride_kd\n        k = tl.load(\n            K + k_offset,\n            mask=(offs_n_cur[None, :] < cur_batch_seq_len) & mask_d[:, None],\n            other=0.0\n        )\n        \n        # Compute QK\n        qk = tl.dot(q, k)\n        qk = qk * sm_scale\n        \n        # Apply causal mask if needed\n        if IS_CAUSAL:\n            qk = tl.where(offs_m[:, None] >= offs_n_cur[None, :], qk, float(\"-inf\"))\n        \n        # Apply sliding window masks (bidirectional)\n        if SLIDING_WINDOW_Q > 0:\n            qk = tl.where(\n                offs_m[:, None] - offs_n_cur[None, :] <= SLIDING_WINDOW_Q,\n                qk,\n                float(\"-inf\")\n            )\n        \n        if SLIDING_WINDOW_K > 0:\n            qk = tl.where(\n                offs_n_cur[None, :] - offs_m[:, None] <= SLIDING_WINDOW_K,\n                qk,\n                float(\"-inf\")\n            )\n        \n        # Apply sequence length mask\n        qk = tl.where(offs_n_cur[None, :] < cur_batch_seq_len, qk, float(\"-inf\"))\n        \n        # Compute softmax (online softmax algorithm)\n        m_ij = tl.maximum(m_i, tl.max(qk, axis=1))\n        p = tl.exp(qk - m_ij[:, None])\n        l_ij = tl.sum(p, axis=1)\n        \n        # Update accumulators\n        alpha = tl.exp(m_i - m_ij)\n        acc = acc * alpha[:, None]\n        \n        # Load value block\n        v_offset = (cur_batch_start_loc + offs_n_cur[:, None]) * stride_vbs + cur_kv_head * stride_vh + offs_d[None, :] * stride_vd\n        v = tl.load(\n            V + v_offset,\n            mask=(offs_n_cur[:, None] < cur_batch_seq_len) & mask_d[None, :],\n            other=0.0\n        )\n        \n        # Update output accumulator\n        acc += tl.dot(p.to(v.dtype), v)\n        \n        # Update m_i and l_i\n        m_i = m_ij\n        l_i = l_i * alpha + l_ij\n    \n    # Normalize and store output\n    acc = acc / l_i[:, None]\n    \n    # Store output\n    out_offset = (cur_batch_start_loc + offs_m[:, None]) * stride_obs + cur_head * stride_oh + offs_d[None, :] * stride_od\n    tl.store(\n        Out + out_offset,\n        acc,\n        mask=(offs_m[:, None] < cur_batch_seq_len) & mask_d[None, :]\n    )",
    "context_attention_fwd": "def context_attention_fwd(\n    q,\n    k,\n    v,\n    o,\n    b_start_loc,\n    b_seq_len,\n    max_input_len,\n    is_causal=True,\n    sliding_window_q=None,\n    sliding_window_k=None,\n):\n    \"\"\"\n    q, k, v: [b * s, head, head_dim]\n    b_start_loc: [b]\n    b_seq_len: [b]\n    out: [b * s, head, head_dim]\n    \"\"\"\n    BLOCK = get_block_size(q.dtype)\n\n    Lq, Lk, _ = q.shape[-1], k.shape[-1], v.shape[-1]\n\n    sm_scale = 1.0 / (Lq**0.5)\n    batch, head = b_seq_len.shape[0], q.shape[1]\n    kv_group_num = q.shape[1] // k.shape[1]\n\n    grid = (batch, head, triton.cdiv(max_input_len, BLOCK))\n    num_warps = 4 if Lk <= 64 else 8\n\n    sliding_window_q = sliding_window_q if sliding_window_q is not None else 0\n    sliding_window_k = sliding_window_k if sliding_window_k is not None else 0\n\n    _fwd_kernel[grid](\n        q,\n        k,\n        v,\n        sm_scale,\n        b_start_loc,\n        b_seq_len,\n        o,\n        q.stride(0),\n        q.stride(1),\n        q.stride(2),\n        k.stride(0),\n        k.stride(1),\n        k.stride(2),\n        v.stride(0),\n        v.stride(1),\n        v.stride(2),\n        o.stride(0),\n        o.stride(1),\n        o.stride(2),\n        kv_group_num=kv_group_num,\n        BLOCK_M=BLOCK,\n        BLOCK_DMODEL=triton.next_power_of_2(Lk),\n        BLOCK_N=BLOCK,\n        IS_CAUSAL=is_causal,\n        SLIDING_WINDOW_Q=sliding_window_q,\n        SLIDING_WINDOW_K=sliding_window_k,\n        num_warps=num_warps,\n        num_stages=1,\n        Lk=Lk,\n    )"
  }
}
EOF"}

